item.text:
{
  "abilities": [
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "He generates 7 stacks if a nearby enemy champion or epic monster dies.",
              "source_id": "wiki:P"
            },
            {
              "quote": "At 7 stacks, Alistar consumes them all to heal himself",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "A nearby enemy champion or epic monster death supplies all seven stacks needed for the heal."
        },
        {
          "citations": [
            {
              "quote": "Triumphant Roar can occur only once every few seconds, though Alistar may still generate stacks before then.",
              "source_id": "wiki:P"
            },
            {
              "quote": "If Alistar is at 7 stacks when Triumphant Roar comes off cooldown, he will roar as soon as it elapses.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Healing has a brief cooldown; stacks can accumulate during it, and a fully charged heal triggers when it ends."
        },
        {
          "citations": [
            {
              "quote": "Alistar does not gain stacks for unsuccessfully trying to apply crowd control, for instance against a crowd control immune target.",
              "source_id": "wiki:P"
            },
            {
              "quote": "Alistar loses all Triumph stacks upon dying.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "Failed crowd control attempts do not generate stacks, and death clears stored stacks."
        },
        {
          "citations": [
            {
              "quote": "Healing occurs simultaneously for Alistar and his allies.",
              "source_id": "wiki:P"
            },
            {
              "quote": "There is a VFX projectile (700 missile speed) that cannot be destroyed by Wind Wall and is unrelated to the actual heal.",
              "source_id": "wiki:P"
            }
          ],
          "status": "supported",
          "summary": "The heal is simultaneous; its visual projectile does not deliver the actual healing."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Alistar charges his roar by stunning or displacing enemy champions or when nearby enemies die.",
              "source_id": "riot:P"
            },
            {
              "quote": "Alistar generates stacks of Triumph from stunning or displacing enemy champions or when a nearby enemy dies.",
              "source_id": "wiki:P"
            }
          ],
          "id": "P.charge",
          "summary": "Charges through stunning or displacing enemy champions and nearby enemy deaths."
        },
        {
          "citations": [
            {
              "quote": "When fully charged he heals himself all nearby allied champions.",
              "source_id": "riot:P"
            },
            {
              "quote": "At max stacks or when a nearby enemy champion or epic monster dies, he heals himself and nearby allied champions.",
              "source_id": "wiki:P"
            }
          ],
          "id": "P.heal",
          "summary": "At full charge, automatically heals himself and nearby allied champions."
        }
      ],
      "slot": "P",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Pulverize can be buffered during Headbutt to cast with reduced cast time when the dash ends.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Q can be buffered during W and casts faster when the dash ends."
        },
        {
          "citations": [
            {
              "quote": "Displacement immunity will also resist the application of the stun.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Displacement immunity also prevents Q's stun."
        },
        {
          "citations": [
            {
              "quote": "This ability will cast from wherever the caster is at the end of the cast time.",
              "source_id": "wiki:Q"
            }
          ],
          "status": "supported",
          "summary": "Q originates from Alistar's position at the end of its cast time."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Alistar smashes the ground, dealing damage to nearby enemies and tossing them into the air.",
              "source_id": "riot:Q"
            },
            {
              "quote": "Alistar smashes the ground beneath him, dealing magic damage to nearby enemies",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.area_damage",
          "summary": "Deals magic damage to enemies around Alistar."
        },
        {
          "citations": [
            {
              "quote": "tossing them into the air.",
              "source_id": "riot:Q"
            },
            {
              "quote": "stunning and knocking them up simultaneously for 1 second.",
              "source_id": "wiki:Q"
            }
          ],
          "id": "Q.knockup",
          "summary": "Knocks nearby enemies into the air and simultaneously stuns them."
        }
      ],
      "slot": "Q",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "If they are within 400 units upon arrival, he deals them magic damage and knocks them back 700 units over 0.5 seconds while also stunning them for 0.75 seconds.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "The hit requires the target to remain within 400 units when Alistar arrives."
        },
        {
          "citations": [
            {
              "quote": "When Pulverize is buffered during the dash, the knock back distance is reduced to 200 units.",
              "source_id": "wiki:W"
            },
            {
              "quote": "Headbutt may be used as a gap-closer to knock up enemies at the target location with Pulverize, additionally overriding Headbutt's knock back.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "Buffering Q during W modifies W's normal knockback, enabling a dash into Q's knockup."
        },
        {
          "citations": [
            {
              "quote": "The knockback direction is in a straight line from Alistar's original location at start of cast and the enemy when Alistar's dash ends.",
              "source_id": "wiki:W"
            },
            {
              "quote": "Headbutt can knock enemies through terrain. The knockback stops short on walls that cannot be surpassed but the disable duration is not changed.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "Knockback direction uses Alistar's starting position and the target's position at dash end. It can cross terrain, but impassable walls stop movement without shortening the disable."
        },
        {
          "citations": [
            {
              "quote": "Displacement immunity will not resist the application of the stun.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "Displacement immunity does not prevent W's stun."
        },
        {
          "citations": [
            {
              "quote": "The CC duration of the ability can be reduced by up to 33.33% Tenacity, due to airborne not being reducible while the stun is.",
              "source_id": "wiki:W"
            }
          ],
          "status": "supported",
          "summary": "Tenacity can shorten the stun portion, but cannot shorten the airborne portion."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Active: Alistar dashes to the target enemy, dealing magic damage, stunning, and knocking them back.",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.targeted_dash",
          "summary": "Dashes toward a targeted enemy."
        },
        {
          "citations": [
            {
              "quote": "Alistar rams a target with his head, dealing damage and knocking the target back.",
              "source_id": "riot:W"
            },
            {
              "quote": "Active: Alistar dashes to the target enemy, dealing magic damage, stunning, and knocking them back.",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.damage",
          "summary": "Deals magic damage when the ram connects."
        },
        {
          "citations": [
            {
              "quote": "knocking the target back.",
              "source_id": "riot:W"
            },
            {
              "quote": "stunning, and knocking them back.",
              "source_id": "wiki:W"
            }
          ],
          "id": "W.knockback",
          "summary": "Knocks the struck target away and stuns them."
        }
      ],
      "slot": "W",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "Each time this damages at least one enemy champion, he generates a stack of Trample that lasts for the remaining duration, stacking up to 5 times.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "Each damage tick that hits at least one champion grants one stack, up to five; hitting multiple champions in a tick does not grant additional stacks."
        },
        {
          "citations": [
            {
              "quote": "At 5 stacks, Alistar's next basic attack on-hit against a champion within 6 seconds ends Trample's effects",
              "source_id": "wiki:E"
            },
            {
              "quote": "The on-hit effect is single-use and Alistar's buff is removed as soon as it is consumed; it can only be applied once by the triggering attack instance.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "The empowered attack has a six-second use window, ends Trample when triggered, and applies its effect only once."
        },
        {
          "citations": [
            {
              "quote": "The on-hit effect can be blocked by spell shield, but the attack cannot.",
              "source_id": "wiki:E"
            },
            {
              "quote": "The on-hit effect is consumed if the attack is blocked, but not if it is dodged or missed while Alistar is blinded. In all cases, the attack's effects are negated as normal.",
              "source_id": "wiki:E"
            },
            {
              "quote": "Does not apply if the triggering attack is dodged, blocked or misses.",
              "source_id": "wiki:E"
            }
          ],
          "status": "supported",
          "summary": "Spell shields can block the empowered effect separately from the attack. A blocked attack consumes the effect; a dodged attack or a miss caused by blindness does not. These failed attacks do not apply the bonus damage."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "Alistar tramples nearby enemy units",
              "source_id": "riot:E"
            },
            {
              "quote": "continually deals magic damage to nearby enemies.",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.periodic_damage",
          "summary": "Repeatedly deals magic damage to nearby enemies while active."
        },
        {
          "citations": [
            {
              "quote": "ignoring unit collision",
              "source_id": "riot:E"
            },
            {
              "quote": "Alistar becomes ghosted",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.ignore_unit_collision",
          "summary": "Allows Alistar to move through units while active."
        },
        {
          "citations": [
            {
              "quote": "gaining stacks if he damages an enemy champion.",
              "source_id": "riot:E"
            },
            {
              "quote": "He generates a stack of Trample each time this damages at least one champion.",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.champion_stacks",
          "summary": "Builds stacks by damaging enemy champions with the trampling damage."
        },
        {
          "citations": [
            {
              "quote": "At full stacks Alistar's next basic attack against an enemy champion deals additional magic damage and stuns them.",
              "source_id": "riot:E"
            },
            {
              "quote": "At max stacks, his next basic attack against a champion within a few seconds will deal bonus magic damage and stun them.",
              "source_id": "wiki:E"
            }
          ],
          "id": "E.empowered_attack",
          "summary": "At full stacks, temporarily empowers his next basic attack against an enemy champion with bonus magic damage and a stun."
        }
      ],
      "slot": "E",
      "unsupported_claims": []
    },
    {
      "advanced_exceptions": [
        {
          "citations": [
            {
              "quote": "True damage cannot be reduced by any means and will deal full damage to Alistar during Unbreakable Will.",
              "source_id": "wiki:R"
            }
          ],
          "status": "supported",
          "summary": "R's damage reduction does not reduce true damage."
        },
        {
          "citations": [
            {
              "quote": "Unbreakable Will's modifier to incoming damage stacks additively with Vladimir's Hemoplague for a total reduction of 45/55/65%.(unexpected)",
              "source_id": "wiki:R"
            }
          ],
          "status": "uncertain",
          "summary": "The Wiki reports an additive interaction with Hemoplague but explicitly marks it unexpected; treat this detailed interaction as provisional."
        }
      ],
      "core_mechanics": [
        {
          "citations": [
            {
              "quote": "removing all crowd control effects on himself",
              "source_id": "riot:R"
            },
            {
              "quote": "Active: Alistar cleanses himself of all crowd control.",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.cleanse",
          "summary": "Cleanses crowd control currently affecting Alistar."
        },
        {
          "citations": [
            {
              "quote": "reducing incoming physical and magical damage for the duration.",
              "source_id": "riot:R"
            },
            {
              "quote": "For the next 7 seconds, he reduces incoming damage.",
              "source_id": "wiki:R"
            }
          ],
          "id": "R.damage_reduction",
          "summary": "Temporarily reduces incoming physical and magic damage."
        }
      ],
      "slot": "R",
      "unsupported_claims": [
        "R grants ongoing immunity to newly applied crowd control.",
        "R reduces true damage."
      ]
    }
  ]
}
